import logging

from ..command import CommandBuilder
from .converter import FastPassOutput

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class FastPass:
    """
    The Fast Pass package features are based on official `query_fastpass_info.sh` CLI.
    Detailed description is available in NetAct Operating Documentation under:
    NetAct Administration -> NetAct Administration Operating Procedures ->
    Administering NetAct fast pass Service package -> Querying fast pass service package information
    """
    SCRIPT_PATH = '/opt/oss/Nokia-fit/bin/query_fastpass_info.sh'

    def __init__(self, ssh_ne3sws_node):
        self.ssh_node = ssh_ne3sws_node

    def _execute_command(self, flags=None, options=None, ignore_errors=False, timeout=60):
        command = CommandBuilder(executable=self.SCRIPT_PATH, flags=flags, options=options).text
        with self.ssh_node as ssh:
            logger.info(f'Executing command: {command}')
            return FastPassOutput(ssh.execute_command(command=command,
                                                      ignore_stderr=ignore_errors,
                                                      timeout=timeout).stdout,
                                  flags=flags,
                                  options=options)

    def get_fast_pass_packages(self, unique=False, all=False, latest=None,
                               fp=None, artifact=None, stdout=True, timeout=120):
        """
        Get information about Fast Pass packages.

        The --list option is used by default - query for all installed packages.

        :param bool unique: If True, returns only the latest installed fast pass packages
            for each package name. Valid only for default --list option.
        :param bool all: Set --all option to query for all packages, including packages
            that are imported but not deployed yet. Higher priority than --list option.
        :param int|string latest: Set --latest option to query for specified number of latest installed packages.
            Support the number within the range of [1, 10000]. Higher priority than --list and --all options.
        :param string fp: Set --fp option to query for detailed information of specified fast pass package.
            Higher priority than --list, --all and --latest options.
       :param string artifact: Set ``--artifact`` option to query for detailed info of specified adaptation fragment.
            The artifact id is the id defined in FIT: fragment/type/adpatationId/adaptationrelease[/buildnumber],
            can be obtained by ``--fp`` option. Highest priority of all available options.
        :param bool stdout: If True, returns stdout as a string,
            otherwise converts it to dict (for ``--fp`` and ``--artifact``) or list of dicts (for other options).
        :param int timeout: Timeout for executing command.
        :return: Command output. Type depends on stdout parameter.
        :rtype: string|dict|list(dict)
        """
        flags = ['--list']
        if unique:
            flags.append('--unique')
        if all:
            flags.append('--all')
        options = {'--latest': latest,
                   '--fp': fp,
                   '--artifact': artifact}
        output = self._execute_command(flags=flags, options=options, timeout=timeout)
        return output.text if stdout else output.structure
